export const rejectionReasons=entry=>[...(entry.kind==='change'?(entry.scenario==='booking'?['slotUnavailable','capacityUnavailable']:['menuUnavailable']):[]),...(entry.scenario!=='booking'&&entry.phase>=13?['preparationStarted']:[]),'verificationRequired'];
export const reasonLabel=(id,lang='ko')=>reasons[id]?.[lang]?.[0]||'';
export const reasonMessage=(id,lang='ko')=>reasons[id]?.[lang]?.[1]||'';
export const DEMO_REVIEWERS=Object.freeze({floor:Object.freeze({id:'demo-floor-haneul',name:'김하늘',role:'floor'}),owner:Object.freeze({id:'demo-owner-jumo',name:'이주모',role:'owner'})});
export const auditTime=(iso,lang='ko')=>new Intl.DateTimeFormat(localeFor(lang),{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date(iso))+' (UTC+7)';
